def cli_guild(name, tibiadata, json):
    """Displays information about a Tibia guild."""
    guild = tibiadata.guild(name)
    if guild is None:
        print("Guild not found.")
        return
    if json:
        print(guild.json(indent=4))
    else:
        print(guild)

